//! Conformance suite: runs every `conformance/cases/*.mbox` program and
//! compares stdout against the matching `conformance/expected/*.txt`.
//!
//! Each pair pins one behavior. Cases carry a comment describing the behavior
//! they exercise; expected files are generated by `scripts/update-expected.sh`
//! and reviewed by hand, so a change in output shows up as a test failure
//! rather than as a silently drifting snapshot.

use std::path::{Path, PathBuf};
use std::process::Command;

/// Repo root, derived from this crate's manifest directory.
fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("crate lives two levels below the repo root")
        .to_path_buf()
}

fn cases_dir() -> PathBuf {
    root().join("conformance/cases")
}

fn expected_path(stem: &str) -> PathBuf {
    root().join("conformance/expected").join(format!("{stem}.txt"))
}

fn case_files() -> Vec<PathBuf> {
    let mut out: Vec<PathBuf> = std::fs::read_dir(cases_dir())
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", cases_dir().display()))
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().map(|x| x == "mbox").unwrap_or(false))
        .collect();
    // Stable order keeps failures reproducible run to run.
    out.sort();
    out
}

/// The conformance cases are checked in, so an empty set means the tree is
/// incomplete rather than that there is nothing to run. Skip instead of failing
/// only when the directory itself is absent, which keeps a bare `cargo test` on
/// a partial checkout from reporting a spurious failure.
fn cases_available() -> bool {
    cases_dir().is_dir()
}

#[test]
fn every_case_has_an_expected_file() {
    if !cases_available() { return; }
    let cases = case_files();
    assert!(!cases.is_empty(), "no conformance cases found in {}", cases_dir().display());
    for path in cases {
        let stem = path.file_stem().unwrap().to_str().unwrap();
        let expected = expected_path(stem);
        assert!(
            expected.exists(),
            "missing expected output for {} — run scripts/update-expected.sh",
            path.display()
        );
    }
}

#[test]
fn cases_produce_the_expected_output() {
    if !cases_available() { return; }
    let exe = env!("CARGO_BIN_EXE_matbox");
    let mut failures: Vec<String> = Vec::new();
    for path in case_files() {
        let stem = path.file_stem().unwrap().to_str().unwrap().to_string();
        let output = Command::new(exe)
            .arg("run")
            .arg(&path)
            .output()
            .unwrap_or_else(|e| panic!("failed to run {}: {e}", path.display()));
        let stdout = String::from_utf8_lossy(&output.stdout).replace("\r\n", "\n");
        let want = std::fs::read_to_string(expected_path(&stem))
            .unwrap_or_else(|e| panic!("cannot read expected for {stem}: {e}"))
            .replace("\r\n", "\n");

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            failures.push(format!(
                "{stem}: exited with {}\nstderr: {stderr}",
                output.status
            ));
            continue;
        }
        if stdout != want {
            failures.push(format!(
                "{stem}: output mismatch\n--- expected ---\n{want}\n--- actual ---\n{stdout}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} conformance case(s) failed:\n\n{}",
        failures.len(),
        failures.join("\n\n")
    );
}